const SIZE = 1000002;
const s = new Array(SIZE).fill(0);
const p = [];
let np = 0;
let minVal = Infinity;

function sieve() {
  for (let i = 2; i < SIZE; i++) {
    if (s[i] === 0) {
      p[np++] = i;
      for (let j = 2; i * j < SIZE; j++) {
        s[i * j] = 1;
      }
    }
  }
}

function solve(x, l) {
  if (x < minVal) minVal = x;
  if (l === 0) return;

  let lf = -1;
  let ox = x;

  for (let i = 0; p[i] * p[i] <= x; i++) {
    if (ox % p[i] === 0) {
      if (p[i] > lf) lf = p[i];
      while (ox % p[i] === 0) ox /= p[i];
    }
  }
  if (ox > 1 && ox !== x) {
    if (ox > lf) lf = ox;
  }

  if (lf === -1) return;

  if (l === 1) {
    x = x - lf + 1;
    if (x < minVal) minVal = x;
    return;
  }

  const limit = lf * Math.floor(x / lf);
  for (let d = x - lf + 1; d < limit; d++) {
    solve(d, l - 1);
  }
}

s[0] = s[1] = 1;
sieve();

const fs = require('fs');
const input = fs.readFileSync(0, 'utf-8').trim();
const x2 = parseInt(input, 10);

solve(x2, 2);
console.log(minVal);

