  if (lf == -1) {
    return;
  }

  if (l == 1) {
    x = x - lf + 1;
    if(x < min)
      min = x;
    return;
  }

  for (d = x - lf + 1; d < lf * (x / lf); d++) {
    solve(d, l - 1);
  }
}

